export function sampleRock(c,id,x,y,size=34){c.save();c.translate(x,y);c.scale(size/34,size/34);c.fillStyle='#302d443f';c.beginPath();c.ellipse(0,13,39,12,0,0,7);c.fill();c.beginPath();[[-35,7],[-30,-18],[-11,-30],[22,-25],[37,-1],[26,20],[-9,24]].forEach(([a,b],i)=>i?c.lineTo(a,b):c.moveTo(a,b));c.closePath();c.fillStyle=({pebbles:'#aa8b88',layers:'#c7a18f',holes:'#656276',salt:'#a78f99',dark:'#58596c',metal:'#aeb7c4'})[id];c.fill();c.strokeStyle='#e0bdad';c.lineWidth=1.5;c.stroke();
 if(id==='pebbles')for(let i=0;i<9;i++){c.fillStyle=i%2?'#dec5b0':'#756a7d';c.beginPath();c.ellipse(-24+i%3*21,-13+Math.floor(i/3)*13,7,4,.3,0,7);c.fill();}
 if(id==='layers'){for(let i=0;i<4;i++){c.strokeStyle=i%2?'#896c7a':'#e7c2a5';c.lineWidth=4;c.beginPath();c.moveTo(-26,-13+i*8);c.lineTo(25,-17+i*8);c.stroke();}}
 if(id==='holes')for(const [a,b,r]of [[-17,-9,7],[9,-14,5],[20,5,7],[-7,10,5]]){c.fillStyle='#343a50';c.beginPath();c.ellipse(a,b,r,r*.7,.3,0,7);c.fill();c.strokeStyle='#a9a1b2';c.lineWidth=1;c.stroke();}
 if(id==='salt'){c.fillStyle='#ede4d3';c.beginPath();c.moveTo(-31,-6);c.lineTo(-10,-20);c.lineTo(18,-17);c.lineTo(30,1);c.lineTo(2,3);c.closePath();c.fill();}
 if(id==='metal'){c.strokeStyle='#e8e4dc';c.lineWidth=3;c.beginPath();c.moveTo(-20,-12);c.lineTo(0,-20);c.lineTo(18,-12);c.stroke();c.fillStyle='#d7dfdf';c.beginPath();c.arc(17,4,4,0,7);c.fill();}
 c.restore();}
export function fieldBackground(c,w,h){const g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,'#2b2d47');g.addColorStop(.45,'#835e72');g.addColorStop(1,'#b67e78');c.fillStyle=g;c.fillRect(0,0,w,h);c.fillStyle='#75556e';c.beginPath();c.moveTo(0,h*.4);c.lineTo(w*.16,h*.18);c.lineTo(w*.37,h*.45);c.lineTo(w*.7,h*.25);c.lineTo(w,h*.5);c.lineTo(w,h);c.lineTo(0,h);c.fill();c.fillStyle='#b4878544';c.fillRect(0,h*.6,w,h*.4);}
export const rockPositions=[[160,160],[360,140],[560,170],[160,330],[360,320],[560,335]];
export function drawField(c,s,rocks){fieldBackground(c,960,420);for(let i=0;i<rocks.length;i++){const rock=rocks[i],[x,y]=rockPositions[i];sampleRock(c,rock.id,x,y,42);c.font='600 24px system-ui';c.textAlign='center';c.fillStyle='#fff0d7';c.fillText(String(i+1),x,y+57);if(s.bag.includes(rock.id)){c.fillStyle='#aee5cc';c.beginPath();c.arc(x+40,y-27,9,0,7);c.fill();}if(s.selected===rock.id){c.strokeStyle='#efd18d';c.lineWidth=3;c.beginPath();c.ellipse(x,y,61,46,0,0,7);c.stroke();}}
 c.fillStyle='#1b3045e8';c.strokeStyle='#d0c9d7';c.lineWidth=8;c.beginPath();c.arc(790,210,137,0,7);c.fill();c.stroke();c.beginPath();c.moveTo(880,310);c.lineTo(927,370);c.lineWidth=22;c.lineCap='round';c.stroke();if(s.selected)sampleRock(c,s.selected,790,210,98);
}
export function drawDrive(c,s,level){c.fillStyle='#24354b';c.fillRect(0,0,420,420);for(let y=0;y<6;y++)for(let x=0;x<6;x++){c.fillStyle=(x+y)%2?'#9e7274':'#ac7d79';c.fillRect(x*70+2,y*70+2,66,66);}
 for(const [x,y]of level.rocks)sampleRock(c,'dark',x*70+35,y*70+34,23);
 for(const [x,y]of level.sand){c.fillStyle='#dec38c';c.fillRect(x*70+5,y*70+5,60,60);c.strokeStyle='#947555';c.lineWidth=2;for(let n=0;n<3;n++){c.beginPath();c.moveTo(x*70+12,y*70+20+n*15);c.quadraticCurveTo(x*70+35,y*70+11+n*15,x*70+57,y*70+20+n*15);c.stroke();}}
 if(s.ghost){c.strokeStyle='#c3f2ed';c.lineWidth=4;c.setLineDash([7,6]);c.beginPath();s.ghost.path.forEach((p,i)=>i?c.lineTo(p.x*70+35,p.y*70+35):c.moveTo(p.x*70+35,p.y*70+35));c.stroke();c.setLineDash([]);for(const p of s.ghost.path){c.fillStyle='#c3f2ed77';c.beginPath();c.arc(p.x*70+35,p.y*70+35,6,0,7);c.fill();}}
 const pose=s.shown??level.start;for(let i=0;i<level.flags.length;i++){const [x,y]=level.flags[i],found=s.run&&s.run.path.some(p=>p.step<s.step&&p.x===x&&p.y===y);c.strokeStyle=found?'#b7e7d1':'#fff0d7';c.lineWidth=3;c.beginPath();c.moveTo(x*70+23,y*70+48);c.lineTo(x*70+23,y*70+14);c.stroke();c.fillStyle=found?'#88bca8':'#efd18d';c.beginPath();c.moveTo(x*70+23,y*70+14);c.lineTo(x*70+52,y*70+25);c.lineTo(x*70+23,y*70+33);c.fill();}
 c.save();c.translate(pose.x*70+35,pose.y*70+35);c.rotate(pose.dir*Math.PI/2);c.fillStyle='#262e43';c.fillRect(-25,-18,9,36);c.fillRect(16,-18,9,36);c.fillStyle='#d3c3da';c.beginPath();c.roundRect(-18,-20,36,40,6);c.fill();c.fillStyle='#bda7f6';c.fillRect(-12,-13,24,18);c.fillStyle='#34475e';c.fillRect(-8,-10,16,9);c.fillStyle='#fff0d7';c.beginPath();c.moveTo(0,-29);c.lineTo(-7,-22);c.lineTo(7,-22);c.fill();c.restore();
}
